// Category A by composition: a box-model editor (an outer margin ring around a padding ring around
// the element) has no headless primitive, but none of its behaviour is ours. Each ring is a React
// Aria `Group` named by its visible label, each side is a React Aria `NumberField` (typing, the
// arrow keys, Page Up/Down, Home/End) or, with `options`, a React Aria `Select` (a list of named
// values, type-ahead), and the link toggle in the centre is a React Aria `ToggleButton`. Read-only,
// each side is a read-only `TextField` showing its value. This file only arranges them and owns
// the look.
import {
  Button,
  Group,
  Input,
  ListBox,
  NumberField,
  Select,
  SelectValue,
  Text,
  TextField,
  ToggleButton,
} from "react-aria-components";
import type { GroupProps, Key } from "react-aria-components";
import { useId, useState, type ReactNode, type Ref } from "react";
import { PopoverContent } from "./Popover";
import { SelectItem } from "./Select";
import { Link } from "./icons";
import "./SpacingField.css";

type SpacingFieldSize = "small" | "medium" | "large";

/** A side of the box, named logically, so the inline sides follow the page's direction. */
export type SpacingFieldSide = "blockStart" | "inlineEnd" | "blockEnd" | "inlineStart";

export type SpacingFieldRing = "margin" | "padding";

/** A side's value: a number, or an option's `id` when `options` is given. `null` means unset. */
export type SpacingFieldValue = number | string | null;

/** One ring's four sides. A side that is absent or `null` is unset and drawn plain. */
export type SpacingFieldSides = Partial<Record<SpacingFieldSide, SpacingFieldValue>>;

/** A named value a side can take in `options` mode, such as a spacing rung. */
export interface SpacingFieldOption {
  /** The value a side reports when this option is chosen. */
  id: string;
  /** What the side and the list show, and what type-ahead matches. */
  label: string;
}

/** Called with the ring's four sides, and the change that produced them: one side, or `"all"` while
 *  the sides are linked. */
export type SpacingFieldChangeHandler = (
  sides: SpacingFieldSides,
  side: SpacingFieldSide | "all",
  value: SpacingFieldValue,
) => void;

export interface SpacingFieldProps extends Omit<GroupProps, "className" | "children"> {
  /**
   * Size axis: the side cells, the centre box and the field's text.
   *
   * @default "medium"
   */
  size?: SpacingFieldSize;
  /** Field label, naming the whole box. Without one, pass `aria-label`, a summary of the box. */
  label?: string;
  /** The padding ring's sides (controlled). */
  padding?: SpacingFieldSides;
  /** The padding ring's sides (uncontrolled). */
  defaultPadding?: SpacingFieldSides;
  /** Called when a padding side changes. */
  onPaddingChange?: SpacingFieldChangeHandler;
  /**
   * The margin ring's sides (controlled). The margin ring is drawn only when this or
   * `defaultMargin` is given, so a field that edits padding alone passes neither.
   */
  margin?: SpacingFieldSides;
  /** The margin ring's sides (uncontrolled). */
  defaultMargin?: SpacingFieldSides;
  /** Called when a margin side changes. */
  onMarginChange?: SpacingFieldChangeHandler;
  /**
   * Named values each side picks from (a spacing rung, say). Given, every side is a list instead of
   * a number, and a side's value is the chosen option's `id`. A set side's list leads with a reset
   * item that sets it back to `null`.
   */
  options?: SpacingFieldOption[];
  /** Number mode: how a side formats its number (a unit, say), passed to each side. */
  formatOptions?: Intl.NumberFormatOptions;
  /**
   * Number mode: the step the arrow keys move a side by.
   *
   * @default 1
   */
  step?: number;
  /** Number mode: the largest value a side takes. Padding never goes below 0; margin may. */
  maxValue?: number;
  /**
   * Shown in an unset side: one text for every side ("0", "auto"), or one per side, such as the
   * value each side resolves to when nothing is set here.
   */
  placeholder?: string | Partial<Record<SpacingFieldSide, string>>;
  /** Whether editing one side sets all four sides of its ring (controlled). */
  isLinked?: boolean;
  /**
   * Whether editing one side sets all four sides of its ring (uncontrolled).
   *
   * @default false
   */
  defaultLinked?: boolean;
  /** Called when the link toggle in the centre is pressed. */
  onLinkedChange?: (isLinked: boolean) => void;
  /** Read-only, the centre box shows this name of the element instead of the link toggle. */
  elementLabel?: string;
  /** Helper text below the box. */
  description?: string;
  /** Shown below the box while `isInvalid` is true. */
  errorMessage?: string;
  /**
   * The visible name of the margin ring.
   *
   * @default "Margin"
   */
  marginLabel?: string;
  /**
   * The visible name of the padding ring.
   *
   * @default "Padding"
   */
  paddingLabel?: string;
  /**
   * Builds each side's accessible name, for a screen that is not in English. The side's value is
   * read after it by the field itself ("Top padding, 16").
   *
   * @default `${ringLabel} ${"Top" | "End" | "Bottom" | "Start"}`
   */
  sideLabel?: (ring: SpacingFieldRing, side: SpacingFieldSide) => string;
  /**
   * The link toggle's accessible name.
   *
   * @default "Link sides"
   */
  linkLabel?: string;
  /**
   * The reset item's text in a set side's list.
   *
   * @default "Reset"
   */
  resetLabel?: string;
  /** Additional class. sd-spacing-field is always retained. */
  className?: string;
  /** Forwarded to the root DOM node. */
  ref?: Ref<HTMLDivElement>;
}

const SIDE_NAMES: Record<SpacingFieldSide, string> = {
  blockStart: "Top",
  inlineEnd: "End",
  blockEnd: "Bottom",
  inlineStart: "Start",
};
// A key no caller's option can hold: the reset item's.
const RESET = "\u0000reset";

/** The controlled/uncontrolled split for a value React Aria does not hold for us. */
function useControlled<T>(value: T | undefined, defaultValue: T) {
  const [own, setOwn] = useState(defaultValue);
  return [value === undefined ? own : value, (next: T) => value === undefined && setOwn(next)] as const;
}

export function SpacingField({
  size = "medium",
  label,
  padding,
  defaultPadding,
  onPaddingChange,
  margin,
  defaultMargin,
  onMarginChange,
  options,
  formatOptions,
  step,
  maxValue,
  placeholder,
  isLinked,
  defaultLinked = false,
  onLinkedChange,
  elementLabel,
  description,
  errorMessage,
  isInvalid,
  marginLabel = "Margin",
  paddingLabel = "Padding",
  sideLabel,
  linkLabel = "Link sides",
  resetLabel = "Reset",
  isDisabled,
  isReadOnly,
  className,
  ref,
  ...props
}: SpacingFieldProps) {
  const id = useId();
  const labelId = `${id}-label`;
  const descriptionId = `${id}-description`;
  const errorId = `${id}-error`;
  const hasMargin = margin !== undefined || defaultMargin !== undefined;
  const [paddingSides, setPadding] = useControlled(padding, defaultPadding ?? {});
  const [marginSides, setMargin] = useControlled(margin, defaultMargin ?? {});
  const [linked, setLinked] = useControlled(isLinked, defaultLinked);
  const showError = isInvalid && !!errorMessage;
  // The box's own helper lines, joined to any the caller names. Each side is described by them
  // too, so a reader on one field hears the error.
  const describedBy =
    [props["aria-describedby"], description && descriptionId, showError && errorId].filter(Boolean).join(" ") ||
    undefined;
  const ringName = (ring: SpacingFieldRing) => (ring === "margin" ? marginLabel : paddingLabel);

  const cell = (
    ring: SpacingFieldRing,
    sides: SpacingFieldSides,
    set: (next: SpacingFieldSides) => void,
    onChange: SpacingFieldChangeHandler | undefined,
    side: SpacingFieldSide,
  ) => {
    const value = sides[side] ?? null;
    const write = (next: SpacingFieldValue) => {
      const all = { blockStart: next, inlineEnd: next, blockEnd: next, inlineStart: next };
      const sidesNext = linked ? all : { ...sides, [side]: next };
      set(sidesNext);
      onChange?.(sidesNext, linked ? "all" : side, next);
    };
    const name = sideLabel ? sideLabel(ring, side) : `${ringName(ring)} ${SIDE_NAMES[side]}`;
    const hint = typeof placeholder === "string" ? placeholder : placeholder?.[side];
    // A set side is tinted, an unset one plain; `data-empty` is the word React Aria's own fields
    // use for "holds no value".
    const empty = value === null || undefined;
    const input = <Input placeholder={hint} className={`sd-spacing-field__input sd-type-body-${size}`} />;
    if (isReadOnly) {
      const shown = value === null ? "" : (options?.find((option) => option.id === value)?.label ??
            (typeof value === "number" ? new Intl.NumberFormat(undefined, formatOptions).format(value) : value));
      return (
        <TextField
          key={side}
          aria-label={name}
          aria-describedby={describedBy}
          value={shown}
          isReadOnly
          isDisabled={isDisabled}
          isInvalid={isInvalid}
          className="sd-spacing-field__side"
          data-side={side}
        >
          <Group role="presentation" isReadOnly data-empty={empty} className="sd-spacing-field__cell">{input}</Group>
        </TextField>
      );
    }
    if (options) {
      // A set side's list leads with the reset item, which writes `null`.
      const items = value === null ? options : [{ id: RESET, label: resetLabel }, ...options];
      return (
        <Select
          key={side}
          aria-label={name}
          aria-describedby={describedBy}
          value={value === null ? null : (value as Key)}
          onChange={(key) => write(key === null || key === RESET ? null : String(key))}
          placeholder={hint}
          isDisabled={isDisabled}
          isInvalid={isInvalid}
          className="sd-spacing-field__side"
          data-side={side}
        >
          <Button data-empty={empty} className="sd-spacing-field__cell">
            <SelectValue className={`sd-spacing-field__value sd-type-body-${size}`} />
          </Button>
          {/* A list of choices in an anchored overlay: the small surface without a Dialog, as Select. */}
          <PopoverContent noDialog size="small">
            <ListBox className="sd-select__listbox" items={items}>
              {(option) => <SelectItem id={option.id}>{option.label}</SelectItem>}
            </ListBox>
          </PopoverContent>
        </Select>
      );
    }
    return (
      <NumberField
        key={side}
        aria-label={name}
        aria-describedby={describedBy}
        value={typeof value === "number" ? value : NaN}
        onChange={(next) => write(Number.isNaN(next) ? null : next)}
        minValue={ring === "padding" ? 0 : undefined}
        maxValue={maxValue}
        step={step}
        formatOptions={formatOptions}
        isDisabled={isDisabled}
        isInvalid={isInvalid}
        className="sd-spacing-field__side"
        data-side={side}
      >
        {/* The Group is the cell: it carries hover and focus-within for the state layer and the
            ring, which an input cannot paint on itself. */}
        <Group role="presentation" data-empty={empty} className="sd-spacing-field__cell">{input}</Group>
      </NumberField>
    );
  };

  const ring = (
    which: SpacingFieldRing,
    sides: SpacingFieldSides,
    set: (next: SpacingFieldSides) => void,
    onChange: SpacingFieldChangeHandler | undefined,
    inner: ReactNode,
  ) => {
    const ringLabelId = `${id}-${which}`;
    // The ring name heads its four sides, one rung below the field label it sits under.
    const ringRole = size === "large" ? "medium" : "small";
    return (
      <Group
        aria-labelledby={ringLabelId}
        isDisabled={isDisabled}
        isInvalid={which === "margin" || !hasMargin ? isInvalid : undefined}
        data-nested={(which === "padding" && hasMargin) || undefined}
        className="sd-spacing-field__ring"
      >
        <span id={ringLabelId} className={`sd-spacing-field__ring-label sd-type-label-${ringRole}`}>
          {ringName(which)}
        </span>
        {/* DOM order follows the rows as they are read: top, then start, centre, end, then bottom. */}
        {cell(which, sides, set, onChange, "blockStart")}
        {cell(which, sides, set, onChange, "inlineStart")}
        {inner}
        {cell(which, sides, set, onChange, "inlineEnd")}
        {cell(which, sides, set, onChange, "blockEnd")}
      </Group>
    );
  };

  const element = isReadOnly ? (
    <span className={`sd-spacing-field__element-name sd-type-label-${size === "large" ? "medium" : "small"}`}>
      {elementLabel}
    </span>
  ) : (
    <ToggleButton
      aria-label={linkLabel}
      isSelected={linked}
      onChange={(next) => {
        setLinked(next);
        onLinkedChange?.(next);
      }}
      isDisabled={isDisabled}
      className="sd-spacing-field__element"
    >
      <Link aria-hidden size="1em" />
    </ToggleButton>
  );
  const paddingRing = ring("padding", paddingSides, setPadding, onPaddingChange, element);

  return (
    <Group
      {...props}
      ref={ref}
      aria-labelledby={label ? labelId : props["aria-labelledby"]}
      aria-describedby={describedBy}
      isDisabled={isDisabled}
      isInvalid={isInvalid}
      isReadOnly={isReadOnly}
      data-size={size}
      className={className ? `sd-spacing-field ${className}` : "sd-spacing-field"}
    >
      {label && (
        <span id={labelId} className={`sd-spacing-field__label sd-type-label-${size}`}>
          {label}
        </span>
      )}
      {hasMargin ? ring("margin", marginSides, setMargin, onMarginChange, paddingRing) : paddingRing}
      {description && (
        <Text id={descriptionId} className={`sd-spacing-field__description sd-type-caption-${size}`}>
          {description}
        </Text>
      )}
      {showError && (
        <Text id={errorId} className={`sd-spacing-field__error sd-type-caption-${size}`}>
          {errorMessage}
        </Text>
      )}
    </Group>
  );
}

.sd-spacing-field {
  --sd-spacing-field-cell-height-current: var(--sd-spacing-field-cell-height-medium);
  --sd-spacing-field-cell-width-current: var(--sd-spacing-field-cell-width-medium);
  --sd-spacing-field-element-icon-size-current: var(--sd-spacing-field-element-icon-size-medium);
  display: flex;
  flex-direction: column;
  gap: var(--sd-spacing-field-gap);
}
.sd-spacing-field[data-size="small"] {
  --sd-spacing-field-cell-height-current: var(--sd-spacing-field-cell-height-small);
  --sd-spacing-field-cell-width-current: var(--sd-spacing-field-cell-width-small);
  --sd-spacing-field-element-icon-size-current: var(--sd-spacing-field-element-icon-size-small);
}
.sd-spacing-field[data-size="large"] {
  --sd-spacing-field-cell-height-current: var(--sd-spacing-field-cell-height-large);
  --sd-spacing-field-cell-width-current: var(--sd-spacing-field-cell-width-large);
  --sd-spacing-field-element-icon-size-current: var(--sd-spacing-field-element-icon-size-large);
}
/* Disabled fades the controls, the side cells and the centre toggle, as a text field fades its
   group: the names (the field label, the ring labels) keep their ink, so they still read. */
.sd-spacing-field[data-disabled] {
  cursor: not-allowed;
}
.sd-spacing-field__side[data-disabled] {
  opacity: var(--sd-state-disabled);
}

.sd-spacing-field__label {
  color: var(--sd-spacing-field-label-foreground);
}

/* A ring: its name in the top-start corner, a side cell on each edge, and what it surrounds (the
   padding ring, or the element) in the middle. The sides are logical and the grid follows the
   page's direction, so the inline-start cell sits on the right of a right-to-left page. */
.sd-spacing-field__ring {
  display: grid;
  /* The side tracks may shrink below their content, so a long option name ends in an ellipsis
     inside its own column instead of running over the centre. */
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  grid-template-rows: auto 1fr auto;
  grid-template-areas:
    "label block-start ."
    "start inner       end"
    ".     block-end   .";
  gap: var(--sd-spacing-field-ring-gap);
  padding: var(--sd-spacing-field-ring-padding);
  border: var(--sd-spacing-field-ring-border-width) solid var(--sd-spacing-field-ring-border);
  background: var(--sd-spacing-field-ring-background-outer);
  border-radius: var(--sd-spacing-field-ring-radius-outer);
  corner-shape: superellipse(var(--sd-radius-curve));
  transition: border-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
/* The padding ring inside the margin ring: in its middle, concentric with it, a step lighter. */
.sd-spacing-field__ring[data-nested] {
  grid-area: inner;
  background: var(--sd-spacing-field-ring-background-inner);
  border-radius: var(--sd-spacing-field-ring-radius-inner);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-spacing-field__ring[data-invalid] {
  border-color: var(--sd-spacing-field-ring-border-invalid);
}

.sd-spacing-field__ring-label {
  grid-area: label;
  align-self: center;
  justify-self: start;
  white-space: nowrap;
  color: var(--sd-spacing-field-ring-label-foreground);
  pointer-events: none;
}

/* A side's field root only places its cell in the ring. */
.sd-spacing-field__side {
  display: grid;
  place-items: center;
  min-inline-size: 0;
}
.sd-spacing-field__side[data-side="blockStart"] {
  grid-area: block-start;
}
.sd-spacing-field__side[data-side="inlineEnd"] {
  grid-area: end;
}
.sd-spacing-field__side[data-side="blockEnd"] {
  grid-area: block-end;
}
.sd-spacing-field__side[data-side="inlineStart"] {
  grid-area: start;
}

/* The cell: a fixed box holding one side's value, plain while unset and tinted once set. A number
   side's cell is a Group around its input; a list side's cell is the Select's trigger button. */
.sd-spacing-field__cell {
  position: relative;
  isolation: isolate;
  display: grid;
  place-items: center stretch;
  min-inline-size: var(--sd-spacing-field-cell-width-current);
  block-size: var(--sd-spacing-field-cell-height-current);
  max-inline-size: 100%;
  padding: 0;
  border: 0;
  border-radius: var(--sd-spacing-field-cell-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: var(--sd-spacing-field-cell-background-set);
  color: var(--sd-spacing-field-cell-foreground-set);
  font: inherit;
  cursor: pointer;
  outline: none;
  transition:
    background-color var(--sd-duration-moderate) var(--sd-easing-standard),
    color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
  --sd-spacing-field-cell-state-hover-current: var(--sd-state-hover-brand-subtle);
}
.sd-spacing-field__cell[data-empty] {
  background: transparent;
  color: var(--sd-spacing-field-cell-foreground);
  --sd-spacing-field-cell-state-hover-current: var(--sd-state-hover);
}
.sd-spacing-field__cell::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-spacing-field__cell[data-hovered]::after {
  background: var(--sd-spacing-field-cell-state-hover-current);
}
/* A number side rings while its input has focus, as a text field does; a list side rings on
   keyboard focus, as a button does. */
.sd-spacing-field__cell[data-focus-within],
.sd-spacing-field__cell[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-spacing-field__cell[data-readonly] {
  cursor: default;
}
.sd-spacing-field__cell[data-readonly]::after {
  display: none;
}

/* A number fills its cell's minimum width and centres, with no inset of its own: a centred number
   reads the same either way, and the four sides keep one width. An option's name sizes its cell
   instead, past that minimum, standing one text inset in from the tint like any text. */
.sd-spacing-field__input,
.sd-spacing-field__value {
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: center;
  font-variant-numeric: tabular-nums;
  color: inherit;
}
.sd-spacing-field__input {
  inline-size: var(--sd-spacing-field-cell-width-current);
  padding-inline: 0;
  background: transparent;
  border: 0;
  outline: none;
  cursor: text;
}
.sd-spacing-field__input::placeholder {
  color: var(--sd-spacing-field-cell-placeholder);
}
.sd-spacing-field__value[data-placeholder] {
  color: var(--sd-spacing-field-cell-placeholder);
}

/* The element in the centre: the toggle that links the four sides of each ring, or, read-only, the
   element's name. */
.sd-spacing-field__element {
  grid-area: inner;
  position: relative;
  isolation: isolate;
  display: grid;
  place-items: center;
  min-inline-size: var(--sd-spacing-field-cell-width-current);
  min-block-size: var(--sd-spacing-field-cell-height-current);
  padding: 0;
  border: var(--sd-spacing-field-element-border-width) solid var(--sd-spacing-field-element-border);
  border-radius: var(--sd-spacing-field-element-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: transparent;
  color: var(--sd-spacing-field-element-foreground);
  font-size: var(--sd-spacing-field-element-icon-size-current);
  cursor: pointer;
  outline: none;
  transition:
    background-color var(--sd-duration-moderate) var(--sd-easing-standard),
    color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
  --sd-spacing-field-element-state-hover-current: var(--sd-state-hover);
  --sd-spacing-field-element-state-pressed-current: var(--sd-state-pressed);
}
.sd-spacing-field__element[data-selected] {
  background: var(--sd-spacing-field-element-background-selected);
  color: var(--sd-spacing-field-element-foreground-selected);
  --sd-spacing-field-element-state-hover-current: var(--sd-state-hover-brand-subtle);
  --sd-spacing-field-element-state-pressed-current: var(--sd-state-pressed-brand-subtle);
}
.sd-spacing-field__element::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-spacing-field__element[data-hovered]::after {
  background: var(--sd-spacing-field-element-state-hover-current);
}
.sd-spacing-field__element[data-pressed]::after {
  background: var(--sd-spacing-field-element-state-pressed-current);
}
.sd-spacing-field__element[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-spacing-field__element[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}
/* Read-only the centre is no control: a box the same size and edge, holding the element's name. */
.sd-spacing-field__element-name {
  grid-area: inner;
  display: grid;
  place-items: center;
  min-inline-size: var(--sd-spacing-field-cell-width-current);
  min-block-size: var(--sd-spacing-field-cell-height-current);
  padding-inline: var(--sd-spacing-field-element-padding-inline);
  border: var(--sd-spacing-field-element-border-width) solid var(--sd-spacing-field-element-border);
  border-radius: var(--sd-spacing-field-element-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  color: var(--sd-spacing-field-element-label-foreground);
  white-space: nowrap;
}

.sd-spacing-field__description {
  color: var(--sd-spacing-field-description-foreground);
}
.sd-spacing-field__error {
  color: var(--sd-spacing-field-error-foreground);
}
